import type { Metadata } from 'next';
import { headers } from 'next/headers';
import Link from 'next/link';

import type { BlogPost } from '@/types/blog';

export const metadata: Metadata = {
  title: 'Home',
  description: 'Welcome to my blog homepage',
  openGraph: {
    title: 'Home - My Blog',
  },
};

async function getRecentPosts(): Promise<BlogPost[]> {
  const response = await fetch(
    'https://jsonplaceholder.typicode.com/posts?_limit=5',
    { cache: 'no-store' }
  );

  if (!response.ok) {
    throw new Error('Failed to fetch recent posts.');
  }

  return (await response.json()) as BlogPost[];
}

export default async function HomePage() {
  const [posts, requestHeaders] = await Promise.all([getRecentPosts(), headers()]);
  const userAgent = requestHeaders.get('user-agent') ?? '';
  const timestamp = new Date().toISOString();

  return (
    <div>
      <h1>Welcome to My Blog</h1>
      <p>Server-side rendered at: {timestamp}</p>
      <p>Your user agent: {userAgent}</p>

      <h2>Recent Posts</h2>
      <ul>
        {posts.map((post) => (
          <li key={post.id}>
            <Link href={`/blog/${post.id}`}>{post.title}</Link>
          </li>
        ))}
      </ul>

      <Link href="/blog" className="button-link">
        View All Posts
      </Link>
    </div>
  );
}
