import { cache } from 'react';
import type { Metadata } from 'next';
import { notFound } from 'next/navigation';

import BackButton from '@/components/BackButton';
import type { BlogComment, BlogPost } from '@/types/blog';

type BlogPostPageProps = {
  params: Promise<{ id: string }>;
};

const getPost = cache(async (id: string): Promise<BlogPost | null> => {
  const response = await fetch(`https://jsonplaceholder.typicode.com/posts/${id}`, {
    next: { revalidate: 300 },
  });

  if (response.status === 404) {
    return null;
  }

  if (!response.ok) {
    throw new Error('Failed to fetch post.');
  }

  const post = (await response.json()) as Partial<BlogPost>;

  if (
    typeof post.id !== 'number' ||
    typeof post.title !== 'string' ||
    typeof post.body !== 'string' ||
    typeof post.userId !== 'number'
  ) {
    return null;
  }

  return post as BlogPost;
});

const getComments = cache(async (id: string): Promise<BlogComment[]> => {
  const response = await fetch(
    `https://jsonplaceholder.typicode.com/posts/${id}/comments`,
    { next: { revalidate: 300 } }
  );

  if (!response.ok) {
    throw new Error('Failed to fetch comments.');
  }

  return (await response.json()) as BlogComment[];
});

export async function generateStaticParams(): Promise<Array<{ id: string }>> {
  try {
    const response = await fetch('https://jsonplaceholder.typicode.com/posts');

    if (!response.ok) {
      return [];
    }

    const posts = (await response.json()) as BlogPost[];

    return posts.slice(0, 10).map((post) => ({ id: post.id.toString() }));
  } catch {
    return [];
  }
}

export async function generateMetadata({
  params,
}: BlogPostPageProps): Promise<Metadata> {
  const { id } = await params;
  const post = await getPost(id);

  if (!post) {
    return {
      title: 'Post Not Found',
      description: 'The requested post could not be found.',
    };
  }

  const description = post.body.slice(0, 160);

  return {
    title: post.title,
    description,
    openGraph: {
      title: post.title,
      description,
    },
  };
}

export default async function BlogPostPage({ params }: BlogPostPageProps) {
  const { id } = await params;
  const [post, comments] = await Promise.all([getPost(id), getComments(id)]);

  if (!post) {
    notFound();
  }

  return (
    <article>
      <BackButton />

      <h1>{post.title}</h1>
      <p>{post.body}</p>

      <h2>Comments ({comments.length})</h2>
      <div className="comments">
        {comments.map((comment) => (
          <div key={comment.id} className="comment">
            <h3>{comment.name}</h3>
            <p>{comment.body}</p>
            <small>By: {comment.email}</small>
          </div>
        ))}
      </div>
    </article>
  );
}
