interface PostRecord {
  id: number;
  title: string;
  content: string;
  createdAt?: string;
}

interface CreatePostBody {
  title?: unknown;
  content?: unknown;
}

const posts: PostRecord[] = [
  { id: 1, title: 'First Post', content: 'This is the first post' },
  { id: 2, title: 'Second Post', content: 'This is the second post' },
];

export async function GET() {
  return Response.json(posts);
}

export async function POST(request: Request) {
  let body: CreatePostBody;

  try {
    body = (await request.json()) as CreatePostBody;
  } catch {
    return Response.json({ error: 'Invalid JSON body' }, { status: 400 });
  }

  const title = typeof body.title === 'string' ? body.title.trim() : '';
  const content = typeof body.content === 'string' ? body.content.trim() : '';

  if (!title || !content) {
    return Response.json(
      { error: 'Title and content are required' },
      { status: 400 }
    );
  }

  const newPost: PostRecord = {
    id: Date.now(),
    title,
    content,
    createdAt: new Date().toISOString(),
  };

  return Response.json(newPost, { status: 201 });
}
---
interface UpdatePostBody {
  title?: unknown;
  content?: unknown;
}

interface RouteParams {
  id: string;
}

function parsePostId(id: string): number | null {
  const parsed = Number.parseInt(id, 10);

  if (!Number.isFinite(parsed) || parsed <= 0) {
    return null;
  }

  return parsed;
}

export async function GET(
  _request: Request,
  { params }: { params: Promise<RouteParams> }
) {
  const { id } = await params;
  const postId = parsePostId(id);

  if (!postId) {
    return Response.json({ error: 'Invalid post id' }, { status: 400 });
  }

  const post = {
    id: postId,
    title: `Post ${id}`,
    content: `This is the content for post ${id}`,
    createdAt: new Date().toISOString(),
  };

  return Response.json(post);
}

export async function PUT(
  request: Request,
  { params }: { params: Promise<RouteParams> }
) {
  const { id } = await params;
  const postId = parsePostId(id);

  if (!postId) {
    return Response.json({ error: 'Invalid post id' }, { status: 400 });
  }

  let body: UpdatePostBody;

  try {
    body = (await request.json()) as UpdatePostBody;
  } catch {
    return Response.json({ error: 'Invalid JSON body' }, { status: 400 });
  }

  const title = typeof body.title === 'string' && body.title.trim()
    ? body.title.trim()
    : `Post ${id}`;
  const content = typeof body.content === 'string' && body.content.trim()
    ? body.content.trim()
    : `Updated content for post ${id}`;

  const updatedPost = {
    id: postId,
    title,
    content,
    updatedAt: new Date().toISOString(),
  };

  return Response.json(updatedPost);
}

export async function DELETE(
  _request: Request,
  { params }: { params: Promise<RouteParams> }
) {
  const { id } = await params;
  const postId = parsePostId(id);

  if (!postId) {
    return Response.json({ error: 'Invalid post id' }, { status: 400 });
  }

  return Response.json({ message: `Post ${id} deleted successfully` });
}
